_PAYLOAD_SHA256 = '742f9638f3f6e939824bb809987d9568ff42627041fcad9f68e813fb3c418b5d'

def start():
    data=base64.b85decode(_PAYLOAD)
    if hashlib.sha256(data).hexdigest()!=_PAYLOAD_SHA256:raise RuntimeError('C10 source payload digest mismatch')
    root=Path(tempfile.mkdtemp(prefix='gpt2_c10_source_'))
    with zipfile.ZipFile(io.BytesIO(data)) as z:
        names=z.namelist()
        if len(names)!=len(set(names)) or any(PurePosixPath(n).is_absolute() or '..' in PurePosixPath(n).parts or '\\' in n for n in names):
            raise RuntimeError('Invalid source ZIP paths')
        if z.testzip():raise RuntimeError('Source ZIP CRC failure')
        m=json.loads(z.read('SOURCE_MANIFEST.json'))
        if set(names)!=set(m)|{'SOURCE_MANIFEST.json'}:raise RuntimeError('Source manifest coverage mismatch')
        for n,h in m.items():
            if hashlib.sha256(z.read(n)).hexdigest()!=h:raise RuntimeError('Source digest mismatch: '+n)
        z.extractall(root)
    modules=[Path(n).stem for n in m if n.endswith('.py')]
    old={n:sys.modules[n] for n in modules if n in sys.modules};paths=sys.path[:]
    for n in modules:sys.modules.pop(n,None)
    sys.path.insert(0,str(root))
    try:
        from launch_c10 import start as launch
        launch(USE_GOOGLE_DRIVE,INPUT_ZIP)
    finally:
        for n in modules:sys.modules.pop(n,None)
        sys.modules.update(old);sys.path[:]=paths

if __name__=='__main__':start()
